/* Help center: the one list of questions and answers (Release 123, seeded in Release 124). Shown by help.html and, for a few, at the top of
   support.html.

   TO ADD OR CHANGE AN ANSWER: edit the entry below. Keep answers short (1 to 4 sentences), in plain words, and check them against how the
   site really works (the code, the help video scripts, the public pages). Entries marked as drafts with D(...) are hidden from visitors until
   the owner has read them at help.html?preview=1 and the entry is switched to E(...). Anything about pricing, timings we promise, privacy
   or legal wording, or research claims starts as a draft.

   E(id, for, topic, help, video, q, a, steps)   a reviewed entry (visitors see it)
   D(id, for, topic, help, video, q, a, steps)   a draft (only help.html?preview=1 shows it)
     id     never change it: the anonymous "faq_open" count records it
     for    who it is for, comma separated: everyone, school, district, teacher, student, parent
     help   the Get help topic to pre-select: cant_sign_in, invitation_or_seat, students_or_classroom, parents, billing_or_license,
            something_broke, other
     video  a help video id from help-videos.js, or ''
     steps  optional list of short steps
   Numbers an owner can change in Settings (lesson limits, idle times) are NOT written here as numbers. Bump the ?v=N on the script tags in
   help.html and support.html when this file changes. */
(function () {
  'use strict';

  var AUDIENCES = [
    { id: 'everyone', title: 'Everyone' },
    { id: 'school', title: 'School administrators' },
    { id: 'district', title: 'District administrators' },
    { id: 'teacher', title: 'Teachers' },
    { id: 'student', title: 'Students' },
    { id: 'parent', title: 'Parents' }
  ];

  function make(reviewed) {
    return function (id, forWho, topic, help, video, q, a, steps) {
      var e = { id: id, for: forWho.split(','), topic: topic, help: help, q: q, a: a, reviewed: reviewed };
      if (video) e.video = video;
      if (steps && steps.length) e.steps = steps;
      return e;
    };
  }
  var E = make(true);
  var D = make(false);

  var ENTRIES = [
    // ================= Signing in and accounts (everyone)
    E('which-sign-in', 'everyone', 'Signing in', 'cant_sign_in', 'A3', `Which sign-in page do I use?`,
      `Teachers, school administrators, district administrators, parents and students each have their own sign-in page, and all five links are in the footer. If you are not sure which one is yours, the person who invited you can tell you.`),
    E('no-user-id', 'everyone', 'Signing in', 'cant_sign_in', 'A1', `Where do I find my user ID?`,
      `There is no separate user ID. Teachers, parents and administrators sign in with their email address and password. Students sign in with a username and a PIN, and their teacher can tell them the username.`),
    E('forgot-password', 'everyone', 'Signing in', 'cant_sign_in', 'A2', `I forgot my password.`,
      `Use the forgot password link on your sign-in page, enter your email, and we will send you a link to choose a new one. The link works for one hour. Students do not have passwords: ask your teacher for a new PIN.`),
    E('reset-nothing-happened', 'everyone', 'Signing in', 'cant_sign_in', 'A2', `I selected Forgot your password and nothing happened.`,
      `Type your email address in the email box first and leave the password box empty. If the email box is blank, the page asks you to enter it before it can send anything.`,
      ['Type your email in the email box.', 'Leave the password empty.', 'Select Forgot your password.']),
    E('reset-message-wording', 'everyone', 'Signing in', 'cant_sign_in', 'A2', `The reset page says "if that email has an account." Does that mean I have no account?`,
      `No. We word it that way on purpose, so nobody can use the page to find out who has an account. If you have one, the link will arrive. If it does not, check the address you typed.`),
    E('link-expired', 'everyone', 'Signing in', 'cant_sign_in', 'A2', `My reset or verification link says it has expired.`,
      `Password reset links last one hour and email verification links last 24 hours. Ask for a new one from your sign-in page. If the new email does not come, see "I never got the email".`),
    E('no-email', 'everyone', 'Signing in', 'cant_sign_in', '', `I never got the email.`,
      `Look in your spam or junk folder first, and check that you used the same address your school invited. Some school mail systems block outside email, so your IT team may need to allow messages from fixernationeducation.com. If it still has not arrived after a few minutes, send us a request. We can give you a one-time link directly, so you do not have to wait for the email.`),
    E('password-not-saving', 'everyone', 'Signing in', 'cant_sign_in', 'A1', `It won't let me save my new password.`,
      `A password needs at least 8 characters, and you have to type it the same way in both boxes. The setup page, the reset page and the sign-up pages all use the same rule.`),
    E('invalid-email-or-password', 'everyone', 'Signing in', 'cant_sign_in', '', `It says "Invalid email or password" and I am sure the password is right.`,
      `That message also appears when no account exists for the email, so check the spelling. It appears too if your account was made with Microsoft and has no password. In that case use Continue with Microsoft, or choose Forgot password to create one.`),
    E('too-many-attempts', 'everyone', 'Signing in', 'cant_sign_in', '', `It says "Too many attempts. Please wait a few minutes and try again."`,
      `Eight wrong passwords for one email within 15 minutes pause sign-in for that email, even if your next try is right. Many failed tries from one network can pause it for everyone on that network. Wait up to 15 minutes, or use Forgot password.`),
    E('verify-email-before-login', 'everyone', 'Signing in', 'cant_sign_in', '', `Sign-in says "Please verify your email before logging in."`,
      `An account you create yourself has to confirm its email first. Open the verification email, or use the resend link that appears under the message. You do not need this step if you joined from a school or teacher invitation, or set your password from a reset link.`),
    E('signed-out-suddenly', 'everyone', 'Signing in', 'cant_sign_in', '', `I was signed in and now I am back at the sign-in page.`,
      `A sign-in lasts 30 days. It ends sooner if you reset your password on another device, if an administrator removes your seat, if your school license or trial ends, or if your account is closed. Sign in again to continue.`),
    E('one-email-two-roles', 'everyone', 'Signing in', 'cant_sign_in', 'A3', `I am a teacher and also an administrator. Do I need two accounts?`,
      `No. One email address can hold more than one role, with the same password. The sign-in page you choose decides where you land: Teacher Login takes you to your classrooms and School Admin takes you to the admin portal.`),
    E('microsoft', 'everyone', 'Signing in', 'cant_sign_in', 'A4', `How does Sign in with Microsoft work?`,
      `Choose Continue with Microsoft in the sign-in box. The first time, we email a confirmation link to the address on your account. Open it and press the button to finish. After that, one click signs you in.`),
    E('ms-attempt-expired', 'everyone', 'Signing in', 'cant_sign_in', 'A4', `After Microsoft sign-in it says "Your Microsoft sign-in attempt expired. Please try again."`,
      `You have 10 minutes to come back from Microsoft, in the same browser you started in. It fails if you took longer, switched browser or device, or your browser would not keep its cookie. Start again from Continue with Microsoft and finish in one go.`),
    E('ms-confirm-link-expired', 'everyone', 'Signing in', 'cant_sign_in', 'A4', `The Microsoft page says "This confirmation link is invalid or has expired."`,
      `The emailed confirmation link works for one hour. Go back to the sign-in box, choose Continue with Microsoft again and open the new email. On the page, press the confirm button. Opening the link alone does not finish the sign-in.`),
    E('microsoft-not-me', 'everyone', 'Signing in', 'cant_sign_in', 'A4', `I got a Microsoft confirmation page I did not ask for. Is it safe?`,
      `If you did not start a sign-in, close the page. Nothing is connected unless you press the confirm button, and Fixer Nation never sees your Microsoft password.`),
    E('account-closed', 'everyone', 'Signing in', 'cant_sign_in', '', `It says my account has been closed.`,
      `An account is closed when we remove the person from our records, for example when someone leaves a school. You cannot sign in until it is reopened. If this is a mistake, send us a request with the email address on the account.`),
    E('internal-server-error', 'everyone', 'Something went wrong', 'something_broke', '', `A page shows "Internal server error".`,
      `Something failed on our side while handling your request, and it is recorded for our staff automatically. Try again in a minute. If it keeps happening, send us a request that says which page you were on and what you pressed.`),

    // ================= Getting help
    E('ask-for-help', 'everyone', 'Getting help', 'other', 'G1', `How do I send you a request, and where do I read the reply?`,
      `Open Get help from the footer, choose a topic, and describe what is happening. If you are signed in we already know who you are. When we reply, a New reply tag appears beside your request on the same page, and you can add to the conversation from there. Please do not put student names, PINs or passwords in a request.`),
    E('check-reply', 'everyone', 'Getting help', 'other', 'G2', `I sent a request without signing in. How do I see the answer?`,
      `Replies are shown on the Get help page, not emailed. Go back to Get help, find the box that says Already sent a request, and enter the reference you were given and the email address you used. Your confirmation email also has the reference.`),
    E('support-reference-not-found', 'everyone', 'Getting help', 'other', 'G2', `Checking my request says "We couldn't find a request with that reference and email."`,
      `The reference and the email have to belong to the same request, and the email must be the one you used when you sent it. Capital letters do not matter. After 5 wrong tries on one reference, or 10 from one network, lookups pause for 15 minutes. If you lost the reference, send a new request and mention the old one.`),
    E('support-status-meanings', 'everyone', 'Getting help', 'other', 'G1', `What do Received, We're on it, Waiting for you and Resolved mean?`,
      `Received means we have your request. We're on it means we are working on it. Waiting for you means we need an answer from you. Resolved means it is done, and if you write back to a resolved request it reopens.`),
    E('contact-team', 'everyone', 'Getting help', 'billing_or_license', '', `How do I contact the team about an order or license?`,
      `Use the Contact page to send your name, email and message, and the team replies by email. For account or classroom trouble, use Get help so we can see who you are.`),

    // ================= About the program (everyone)
    E('what-is-fne', 'everyone', 'About the program', 'other', '', `What is Fixer Nation Education?`,
      `Fixer Nation Education is a daily social-emotional learning program for K-12 schools. Each school morning it gives teachers a short lesson, along with a digital classroom for assigning lessons and tracking results.`),
    E('what-is-2d-sel', 'everyone', 'About the program', 'other', '', `What does "2D SEL" mean?`,
      `The "2D" stands for digital delivery: social-emotional learning (SEL) delivered digitally. Teachers can use the lessons in the Digital Classroom, show them on a classroom display, or print the materials.`),
    E('grade-levels', 'everyone', 'About the program', 'other', '', `Which grade levels does Fixer Nation cover?`,
      `Every grade from K to 12. Each lesson comes in versions for elementary, middle and high school, and the lesson library can be filtered by level.`),
    E('lesson-length', 'everyone', 'About the program', 'other', '', `How long does a daily lesson take?`,
      `A Morning Boost lesson takes about five to fifteen minutes. The video runs under five minutes, and the rest of the time is for discussion, reflection and a short quiz.`),
    E('morning-boost-what', 'everyone', 'About the program', 'other', '', `What is a Morning Boost?`,
      `A Morning Boost is the daily lesson. A new one is released every weekday, and each belongs to one of eight program themes. The steps are watch, discuss, reflect, assess and reinforce.`),
    E('lesson-kit-contents', 'teacher,school', 'About the program', 'other', '', `What comes with each lesson?`,
      `Each lesson has eight parts: a video, a read-along script, a teacher guide, a student handout, a quiz, an answer key, a classroom poster, and objectives with alignment.`),
    E('program-themes', 'everyone', 'About the program', 'other', '', `What topics do the lessons cover?`,
      `Lessons cycle through eight themes: character and values, resilience and mindset, healthy decisions, communication and relationships, life skills, leadership and responsibility, wellness and self-care, and emotional intelligence.`),
    E('issues-to-answers', 'teacher,school', 'About the program', 'other', '', `What is the Issues-to-Answers method?`,
      `It is the five-step routine behind every lesson: recognize the issue, understand the impact, consider possible answers, choose a responsible response, then reflect and reinforce. It is our own framework and has not been externally validated.`),
    E('delivery-options', 'teacher', 'About the program', 'other', '', `Do I need student devices to teach a lesson?`,
      `No. You can run a lesson through the Digital Classroom, show it on a classroom display such as a digital whiteboard, or print the materials.`),
    E('brain-games-what', 'everyone', 'Brain Games', 'other', '', `What are Brain Games?`,
      `Brain Games are short games that build reading, math, thinking skills, decision-making and everyday life skills. They are grouped into literacy, math, thinking skills, SEL and character, and wellness and life skills.`),
    E('brain-games-grades', 'everyone', 'Brain Games', 'other', 'S4', `Are Brain Games available for different ages?`,
      `Yes. Games are sorted into four grade bands: Discover for K-2, Explore for grades 3-5, Challenge for grades 6-8 and Advance for grades 9-12. You can filter the list by grade band and by focus area.`),
    E('see-sample-lessons', 'everyone', 'About the program', 'other', '', `Can I look at lessons before my school buys a license?`,
      `The lesson library page shows a sample of lessons and lets you filter by grade level and series. The full kits are for licensed schools.`),
    E('state-standards-use', 'everyone', 'Standards', 'other', 'E1', `How do I see how Fixer Nation lines up with my state's standards?`,
      `Open the state standards page and choose your state. You see the type of framework, the date we last checked it, and a link to the state's own page, which is always the source of truth. Under each standard, open Where Fixer Nation connects.`),
    E('state-standards-missing', 'everyone', 'Standards', 'other', 'E1', `My state isn't in the standards list.`,
      `A state appears once our team has checked its standards against the state's own published documents. If yours is not there yet, it has not been checked. You can send us a request to ask.`),
    E('state-standards-endorsed', 'everyone', 'Standards', 'other', 'E1', `Does this mean my state or CASEL has approved Fixer Nation?`,
      `No. These matches are Fixer Nation's own mapping, and they do not mean your state, your district or CASEL has endorsed or certified the program. A direct match means the lesson teaches the same skill, and a supporting connection reinforces part of it.`),
    E('affiliate-apply', 'everyone', 'Affiliate program', 'other', 'F1', `How do I join the affiliate program and get paid?`,
      `Apply with your name, email and company if you have one. A person here reads your application, and if it is a fit we agree on a commission rate and territory and send your referral link. Purchases made through your link in the next 90 days are credited to you.`),
    E('affiliate-dashboard-numbers', 'everyone', 'Affiliate program', 'billing_or_license', 'F1', `What do Pending, Owed and Paid mean on my affiliate dashboard?`,
      `Pending is money that is not confirmed yet. Owed is confirmed and waiting to be paid out. Paid has already been sent to you. Your commission history lists every sale and what it paid.`),
    E('affiliate-territory', 'everyone', 'Affiliate program', 'other', 'F1', `How do I ask for a territory, or a different one?`,
      `Your account page shows your commission rate and your territory, and you can request a territory right there. Each territory (a state plus a county) has one active affiliate, so we review every request and confirm yours or suggest an open one.`),

    // ================= School administrators
    E('welcome-email-steps', 'school,district', 'First sign-in', 'cant_sign_in', 'A1', `I got a welcome email as an administrator. What do I do with it?`,
      `Select Set Password and Access Portal, choose a password of at least 8 characters, type it again and save. That one step confirms your email and signs you in, so there is no second email to open. The link works for seven days and can be used once.`,
      ['Open the welcome email (check spam if you cannot find it).', 'Select Set Password and Access Portal.', 'Type a password twice and select Save password.', 'Select Continue.']),
    E('welcome-email-sign-in-button', 'school,district', 'First sign-in', 'cant_sign_in', 'A1', `My welcome email has a sign-in button, not a Set Password button.`,
      `That happens when you already had a Fixer Nation account. Sign in with your usual password. If you do not remember it, choose Forgot your password on the sign-in page.`),
    E('welcome-link-expired', 'school,district', 'First sign-in', 'cant_sign_in', 'A2', `My welcome link says it has expired.`,
      `A welcome or purchase email link lasts seven days. Use Forgot your password on your sign-in page for a new link, which then lasts one hour. A district administrator can also choose Resend Welcome for you. If neither works, send us a request.`),
    E('admin-access-denied-login', 'school,district', 'First sign-in', 'cant_sign_in', 'A3', `It says "This account does not have School License Administrator access." My password worked.`,
      `Your password is right, but that email has no active administrator assignment. Common causes are signing in with a different email than the one invited, or access that was removed. Use the invited address, ask the person who invited you, or send us a request. The District Admin page gives the same kind of message.`),
    E('find-district-login', 'district', 'First sign-in', 'cant_sign_in', 'A3', `I can't find the District Admin sign-in.`,
      `District administrators sign in from the footer link. The Log In menu at the top lists teachers, students, parents and school administrators only. In the footer, look in the Access column for District Admin.`),
    E('microsoft-admin-pages', 'school,district', 'First sign-in', 'cant_sign_in', 'A4', `Why is there no Continue with Microsoft button on the admin sign-in page?`,
      `Microsoft sign-in is only in the Log In window on the public site. The School Admin and District Admin pages use email and password.`),
    E('dashboard-numbers', 'school', 'Your portal', 'invitation_or_seat', 'B1', `What do the numbers and the bar on my dashboard mean?`,
      `The three numbers are active teachers, seats still available, and invitations waiting for an answer. The bar shows how much of your license is in use. Your own seat as an administrator is not counted.`),
    E('school-license-banner', 'school', 'Your portal', 'billing_or_license', 'B1', `The banner at the top of my portal turned yellow, or red.`,
      `The banner shows your license end date. It turns yellow when 30 days or fewer are left and red once the license has expired. For a renewal, send us a request.`),
    E('seat-warning', 'school', 'Your portal', 'invitation_or_seat', 'B1', `A warning about seats appeared on my dashboard.`,
      `The dashboard warns you at 90 percent of your seats and again when they are all used. It means you are nearly out of room. Send us a request if you need more seats.`),
    E('more-than-one-school', 'school', 'Your portal', 'other', 'B1', `I manage two schools. How do I switch between them?`,
      `A school selector appears at the top of the menu when you manage more than one school. Pick a school there and every page switches to it.`),
    E('school-levels', 'school', 'Your portal', 'invitation_or_seat', 'B9', `What can each administrator permission level do?`,
      `Read Only administrators can look but change nothing. Secondary administrators can invite, resend, extend, deactivate, edit grade levels and publish branding, but cannot revoke an invitation, remove a teacher or revoke a seat. Primary administrators can do all of it. The level is set per school, and the Organization page shows who holds which one.`),
    E('role-blocked-message', 'school', 'Your portal', 'invitation_or_seat', 'B9', `A button gave a message that my role is read-only, or that only a primary administrator can do it.`,
      `Nothing is broken. The message means your administrator level does not allow that action, and nothing was sent or changed. To change a level, send us a request.`),
    E('school-need-help-changes', 'school', 'Your portal', 'billing_or_license', 'B9', `How do I add seats, renew, add an administrator or change a level?`,
      `These are not done in the portal. Administrators are set up by Fixer Nation or by your district. Send us a request and include your school's domain so we can find your account quickly.`),
    E('school-cant-invite', 'school', 'Teachers and seats', 'invitation_or_seat', 'B10', `Why can't I invite teachers yet?`,
      `Invitations open once your license is active. While a payment is still pending, or on some trial licenses, the invite button stays off, and the page tells you which case applies. If you think your license should be active, send us a request.`),
    E('school-po-waiting', 'school', 'Teachers and seats', 'billing_or_license', 'B10', `We paid by purchase order. Why can't I invite teachers yet?`,
      `With a purchase order, invitations open as soon as we record that your signed purchase order has arrived. You do not have to wait for payment. Until then the banner says we are waiting for your purchase order. Send us a request and we will check where it stands.`),
    E('school-seats-full', 'school,district', 'Teachers and seats', 'invitation_or_seat', 'B10', `It says "No available licenses" or "No licenses remaining", but fewer teachers signed up than I expected.`,
      `Registered teachers, deactivated teachers and invitations still waiting each use a seat. Revoked invitations and removed teachers release theirs. School and district administrators never use a seat, even if they also teach. To add seats, send us a request.`),
    E('invite-required-fields', 'school', 'Teachers and seats', 'invitation_or_seat', 'B2', `What do I have to fill in to invite a teacher?`,
      `An email address, a first and last name, and at least one grade level: ES for elementary, MS for middle school, HS for high school and HE for higher education. Department, role title, subject area and a personal message are optional. When the teacher accepts, the grade levels you chose are added to their own.`),
    E('invite-holds-seat', 'school', 'Teachers and seats', 'invitation_or_seat', 'B2', `I just sent an invitation and my available seats went down. Why?`,
      `A seat is held for the teacher the moment you send the invitation, so pending invitations count toward your seat total. If you revoke the invitation, the held seat is released.`),
    E('invite-existing-account-note', 'school', 'Teachers and seats', 'invitation_or_seat', 'B2', `A note says this email already belongs to someone with an account. Can I still invite them?`,
      `Yes. The note is only a heads-up. That person can accept your invitation with their existing account.`),
    E('active-invitation-exists', 'school', 'Teachers and seats', 'invitation_or_seat', 'B4', `It says "An active invitation already exists for this email" or "already registered under this license."`,
      `The first means an earlier invitation for that address is still Pending or Opened, so use Resend or Extend on it instead of sending a new one. The second means the teacher already holds a seat here. In a bulk upload both are counted as skipped, not failed.`),
    E('bulk-invite-steps', 'school', 'Teachers and seats', 'invitation_or_seat', 'B3', `How do I invite my whole staff at once?`,
      `Use the CSV template on the Invitations page. One upload can hold up to 200 teachers. The columns are email, first_name, last_name, grade_level, role, department and subject_area, and several grade levels are separated by a semicolon, like ES;MS.`,
      ['Download the template from the Invitations page.', 'Add one teacher per row and save it as a CSV.', 'Select Bulk Invite and add the file.', 'Check the preview count, then select Send Invitations.']),
    E('bulk-rows-skipped', 'school', 'Teachers and seats', 'invitation_or_seat', 'B3', `My bulk upload skipped some rows, or the columns look scrambled.`,
      `A row is skipped if the first or last name is missing or there is no grade level. A person who was already invited or already has a seat is skipped too, which is not a problem. A comma inside a cell splits it in two, so keep values free of commas. The summary gives a reason for each row that could not be sent.`),
    E('invite-status-badges', 'school', 'Teachers and seats', 'invitation_or_seat', 'B4', `What do Pending, Opened, Registered, Expired and Revoked mean?`,
      `Pending means the invitation was sent. Opened means the teacher looked at the email. Registered means they joined, and you get an email about it. Expired means 14 days passed with no answer. Revoked means you cancelled it.`),
    E('school-invite-expired', 'school', 'Teachers and seats', 'invitation_or_seat', 'B4', `A teacher's invitation expired, or they never opened it.`,
      `Invitations last 14 days. Resend sends a fresh email with a new link and a new 14-day window. Extend gives more time without sending another email, which suits a teacher who is away. A status badge shows where each one stands.`),
    E('resend-limit-reached', 'school', 'Teachers and seats', 'invitation_or_seat', 'B4', `Resend says "Resend limit (5) reached" or "Cannot resend a revoked invitation."`,
      `Each invitation can be resent 5 times, and only while it is Pending, Opened or Expired. Extend has no count and gives a fresh 14 days. A revoked invitation cannot be resent, so send a new invitation to that address.`),
    E('renew-invite-no-seat', 'school', 'Teachers and seats', 'invitation_or_seat', 'B4', `Resend or Extend says "Every seat is in use right now, so this invitation can't be renewed."`,
      `When an invitation passes its date its reserved seat is released, and other invitations or teachers may have taken every seat since. Free a seat, for example by revoking an unused invitation, or send us a request to add seats.`),
    E('opened-invite-holds-seat', 'school', 'Teachers and seats', 'invitation_or_seat', 'B4', `An invitation shows Opened and its date has passed, but its seat still counts as used.`,
      `Only invitations still marked Pending expire on their own, which releases the seat. Once a teacher opens the link the status is Opened and the seat stays reserved. A primary administrator can revoke it to free the seat, or you can Extend it so the teacher can finish.`),
    E('school-teacher-left', 'school', 'Teachers and seats', 'invitation_or_seat', 'B5', `A teacher left. How do I free their seat?`,
      `On your teacher roster, remove the teacher. Their seat goes back to your pool so you can invite someone else. Removing needs a reason, signs the teacher out and cannot be undone. A primary administrator has to do it.`),
    E('deactivate-vs-remove', 'school', 'Teachers and seats', 'invitation_or_seat', 'B5', `Should I deactivate or remove a teacher who is leaving?`,
      `Deactivate is for a teacher on leave: they keep their account, their access pauses and their seat stays used, so you can reactivate them later. Remove is for someone leaving for good and frees the seat.`),
    E('roster-removed-record', 'school', 'Teachers and seats', 'invitation_or_seat', 'B5', `I removed a teacher and they disappeared from my roster.`,
      `Set the roster filter to All teachers. The removed teacher shows there as Revoked, with your reason in the Notes column.`),
    E('roster-not-joined', 'school', 'Teachers and seats', 'invitation_or_seat', 'B5', `How do I see which invited teachers have not joined yet?`,
      `On the Roster page, choose the filter Invited, not joined yet. A seat still waiting on a teacher has a Revoke button, which does the same job as revoking from the Invitations page.`),
    E('roster-no-students', 'school', 'Teachers and seats', 'students_or_classroom', 'B5', `Where are the students on my Roster page?`,
      `Students are not listed there. The Roster shows teachers who hold a seat, and teachers manage their own students inside their classrooms.`),
    E('school-branding', 'school,district', 'Branding', 'other', 'B6', `How do I add my school's logo and colors?`,
      `Open Branding, upload your logo, choose your colors, check the preview, and publish. Teachers and students see the new look once you publish.`),
    E('logo-rejected', 'school,district', 'Branding', 'other', 'B6', `My logo won't upload, or it looks blurry.`,
      `Use a PNG, JPG, WebP or SVG file no larger than 2 MB. Pictures other than SVG should be at least 200 by 100 pixels or they look blurry, and a transparent PNG works best. Edit Crop trims the logo and never changes your original file.`),
    E('branding-not-live', 'school,district', 'Branding', 'other', 'B6', `I set my colors and uploaded a logo, but nobody sees them.`,
      `Uploads, colors and crops are saved as a draft only. Nothing changes for anyone until you press Publish Branding and confirm. A note under the buttons tells you when changes are not published.`),
    E('branding-reset-name', 'school,district', 'Branding', 'other', 'B6', `How do I start over on branding, or fix my school name?`,
      `Reset to FNE Default puts the standard look back and removes your logo after you confirm. The school or district name at the top of the page cannot be edited there, so send us a request if it needs a correction.`),
    E('branding-which-wins', 'school,district', 'Branding', 'other', 'C2', `Why do teachers see the district's logo instead of ours, or the other way round?`,
      `A school's own published branding always wins. If a school has none published, it shows the district's. If neither exists, people see the standard Fixer Nation look.`),
    E('school-safety-alerts', 'school', 'Safety alerts', 'other', 'B8', `Who gets student safety alerts, and why did one go out?`,
      `Students write short reflections and goals in their lessons, and we check that writing. If something serious comes up, an alert email goes to the people you chose on the Organization page. Add or remove people there.`),
    E('safety-alert-categories', 'school', 'Safety alerts', 'other', 'B8', `Can one person get only certain kinds of safety alerts?`,
      `Yes. On the Organization page, choose a category before you select Add. Leave it on all categories to make someone the catch-all, and keep at least one catch-all so no alert is missed. Use an address someone checks every day.`),
    E('reports-where', 'school', 'Reports', 'other', 'B7', `Where do I see how many seats are in use and who made a change?`,
      `Open Reports. Utilization shows the percentage of your license in use. The Activity Log records invitations sent and seats changed, 50 entries at a time. Export CSV is on the Teachers and Invitations tabs only.`),
    E('school-trial-not-set-up', 'school', 'Your portal', 'billing_or_license', 'B10', `Branding or safety alerts says it isn't set up, and we are on a trial.`,
      `A trial license may not have a school domain or school record attached, so a few features say they are not set up. When your school moves to a full license we finish that setup for you.`),
    E('license-expired-what-happens', 'school,teacher', 'Your portal', 'billing_or_license', '', `The banner says "Your license expired on" a date. What happens when a license ends?`,
      `A license works through its end date. The next night it is marked expired, every teacher seat is switched off and those teachers are signed out. Classrooms, rosters and lesson picks are kept. When the license is renewed, the seats that expiry switched off come back, but not ones an administrator deactivated on purpose.`),
    E('quote-accept-pay', 'school', 'Quotes and buying', 'billing_or_license', 'D1', `How do I accept our school's quote and pay?`,
      `Open the quote email and select Accept Quote. Check the details, then choose a tab: purchase order or credit card. Card payment happens on Stripe's secure page, and your card details are never entered on our site.`,
      ['Select Accept Quote in the email.', 'Review the school, seats, valid-until date and total.', 'Choose the purchase order or credit card tab.', 'Submit the PO number, or select Pay now.']),
    E('quote-po-number', 'school', 'Quotes and buying', 'billing_or_license', 'D1', `Accepting by purchase order says "A Purchase Order number is required."`,
      `A quote with an amount to pay needs a PO number to accept by PO. The license then stays pending until we receive the PO, and teachers can be invited once it opens. A $0 quote, such as a free trial, needs no PO and activates immediately.`),
    E('quote-expired', 'school', 'Quotes and buying', 'billing_or_license', 'D1', `My quote link says "This quote has expired or isn't available anymore."`,
      `A quote can be accepted until the end of its valid-until date. After that, or if the link is wrong, this page appears. A quote already accepted says "This quote has already been accepted." Send us a request to get a new quote.`),
    E('quote-someone-else', 'school', 'Quotes and buying', 'invitation_or_seat', 'D1', `I accepted the quote but someone else should run the account.`,
      `After your order is confirmed, choose Invite someone else to manage the account and enter their email. Each accepted quote allows one such invitation, within 7 days of accepting, and their setup link also lasts 7 days. After that, send us a request to add an administrator.`),
    E('quote-card-password', 'school', 'Quotes and buying', 'billing_or_license', 'D1', `I paid our quote by card. Where do I set my password?`,
      `The link to set your password is in the confirmation email we send you. If you paid by purchase order, you can set your password right on the page after your order is confirmed.`),
    E('license-types', 'school,district,teacher', 'Licensing', 'billing_or_license', '', `What license types are there?`,
      `An Individual Educator license is for one teacher with one classroom. A School License is for a whole building with many teacher seats. A District License covers several schools, with an admin view for each school and one for the district.`),
    E('who-buys-license', 'teacher,school', 'Licensing', 'billing_or_license', '', `Who buys a license, and what does it cover?`,
      `A principal or curriculum coordinator usually buys a school license. It gives every teacher in the building the full lesson library, the Digital Classroom and a school admin portal. District plans cover several buildings.`),
    E('own-teacher-account', 'school', 'Licensing', 'invitation_or_seat', '', `Does every teacher need their own account?`,
      `Yes. Each teacher has an individual account tied to the school's license, so progress and reporting stay accurate. Accounts use each teacher's school email address.`),
    E('start-small', 'school,district', 'Licensing', 'billing_or_license', '', `Can we start with just a few teachers?`,
      `Yes. There is no minimum number of seats, so a school can begin with one teacher or a pilot group and add more as staff join.`),
    E('how-to-buy', 'school,district', 'Licensing', 'billing_or_license', '', `How can a school pay for a license?`,
      `You can buy directly by card or ask for a custom proposal. Purchase orders are accepted, and a school paying by purchase order gets an invoice to approve. The license activates once payment is confirmed.`),
    E('get-quote', 'school,district', 'Licensing', 'billing_or_license', '', `How do I get a quote or proposal?`,
      `Fill in the inquiry form on the School and District Licensing page with your role, number of teachers and grade levels. The proposal covers the number of teacher licenses, the term, pricing for your size and optional services, with no commitment.`),
    E('admin-dashboard-data', 'school,district', 'Your portal', 'other', '', `What can administrators see in the school dashboard?`,
      `How many teachers are assigning lessons, how many students complete each one, and how much the program is used across the school. The admin view does not show individual student information or grades.`),
    E('single-teacher-license-email', 'teacher', 'Licensing', 'billing_or_license', 'T8', `I bought a teacher license. How do I find it?`,
      `Create an account, or log in, with the same email you used at checkout. Then open My Licenses from the account menu, where your license is listed with its status and dates.`),
    E('teacher-group-license', 'teacher,school', 'Licensing', 'billing_or_license', 'T8', `We want to buy for a whole school or district. Do I use Buy Now?`,
      `No. On the licenses page, use the link under the heading to request a group proposal. Buy Now is for a teacher buying a license for themselves, paid by card on Stripe.`),
    E('teacher-no-school-license', 'teacher', 'Licensing', 'billing_or_license', '', `My school does not have a license. What can I do?`,
      `Share the licensing page with your principal or curriculum coordinator. If you would rather not wait, you can buy a single-teacher license yourself from the Teacher Registration page.`),

    // ================= District administrators
    E('district-what-can-do', 'district', 'Your portal', 'invitation_or_seat', 'C1', `As a district administrator, can I invite teachers or see classrooms?`,
      `No. The district portal covers the dashboard, district branding, school administrators and the Portrait of a Graduate. Each school's own administrators invite teachers, and you see seat counts only. Use Schools to add an administrator for a school in your district.`),
    E('district-dashboard-flags', 'district', 'Your portal', 'other', 'C1', `What do the attention items on the district dashboard mean?`,
      `A school is flagged if its license ends within 90 days, it is waiting on a purchase order, it has no school administrator, it is 90 percent full or more, or fewer than 25 percent of its seats are in use 60 days after starting. The dashboard shows counts only, never teacher names or student data.`),
    E('district-status-labels', 'district', 'Your portal', 'billing_or_license', 'C3', `What do "Waiting for purchase order", "Payment pending", "Ending soon" and "In force" mean?`,
      `"Waiting for purchase order" means the PO has not been received, so teachers cannot be invited yet. "Payment pending" means the invoice is not marked paid. "Ending soon" is a license in its last 30 days. "In force" is a working license.`),
    E('district-school-missing', 'district', 'Schools and administrators', 'other', 'C3', `A school is missing from my Schools page, or the page is empty.`,
      `A school appears once it has a license and has been linked to your district. An empty page means no school has been linked yet. Send us a request with the school's name and we will link it.`),
    E('district-seats-not-shown', 'district', 'Schools and administrators', 'other', 'C3', `Where are teacher lists, seats used and license dates for our schools?`,
      `The Schools page does not show teacher lists, seats used or reports. Those belong to each school's own administrators. The banner at the top tells you how many schools are expired or expiring within 30 days.`),
    E('district-add-admin', 'district', 'Schools and administrators', 'invitation_or_seat', 'C4', `How do I add a school administrator?`,
      `On Schools, pick the school, enter the person's name and email, and send the invitation. From the same row you can later resend the welcome email, send a password reset, edit or remove them.`),
    E('district-admin-cant-sign-in', 'district', 'Schools and administrators', 'cant_sign_in', 'C4', `A school administrator can't sign in, or shows Pending Setup.`,
      `Find them on Schools. Pending Setup means they have not chosen a password yet, so choose Resend Welcome. If they have signed in before, the button is Reset Password, which sends a reset link that lasts one hour.`),
    E('district-edit-remove-admin', 'district', 'Schools and administrators', 'invitation_or_seat', 'C4', `How do I change a school administrator's level, or take away their access?`,
      `On the school's card, select Edit to change the level. Select Revoke and confirm to remove their administrator access. Their account stays, but they can no longer manage that school.`),
    E('pog-rules', 'district', 'Portrait of a Graduate', 'other', 'C5', `I can't finish adding my framework, or I picked the wrong type.`,
      `Every framework needs a link to your district's official page and a date. The type cannot be changed after you save. You can record up to 3 frameworks, each with up to 60 standards.`),
    E('pog-standard-summary', 'district', 'Portrait of a Graduate', 'other', 'C5', `How should I write the summary for a standard?`,
      `Write a short summary of up to 600 characters in your own words. Please do not copy long passages from your district's document, because the link to your official page covers the rest. You can edit or delete a standard any time.`),
    E('pog-cant-submit', 'district', 'Portrait of a Graduate', 'other', 'C6', `Submit for review won't work.`,
      `The framework needs at least one standard, and you must tick the box saying it is your district's official framework and that you are authorized to submit it. After you submit, the status changes to In review.`),
    E('pog-note-private', 'district', 'Portrait of a Graduate', 'other', 'C6', `Will the public see the note I add when I suggest a connection?`,
      `No. Your note stays private and only our team sees it. We write the public explanation ourselves. You can select Remove suggestion on any connection you added.`),
    E('pog-status-meaning', 'district', 'Portrait of a Graduate', 'other', 'C7', `What do Draft, In review and Published mean, and will I get an email?`,
      `Draft is yours alone. In review means we are working on it. Published means it is live on our website. We do not email you when a framework is approved, so check the page, and send us a request if it has been a while.`),
    E('pog-edit-offline', 'district', 'Portrait of a Graduate', 'other', 'C7', `My published framework disappeared from the website after I edited it.`,
      `Editing a published framework takes it offline until we review it again. To pause one without losing it, use Take back to draft. Delete framework removes it for good, with no undo.`),
    E('district-pog', 'district', 'Portrait of a Graduate', 'other', 'C5', `How do we record our Portrait of a Graduate?`,
      `Add your framework and its standards first, then suggest where our lessons and games fit, and send it for review. Two short videos walk through each part.`),

    // ================= Teachers
    E('teacher-accept-invite', 'teacher', 'Getting in', 'invitation_or_seat', 'T1', `How do I accept my school's invitation?`,
      `Open the email from your school administrator and choose the link. Create a password or use Microsoft, and you land in your teacher portal. The link works for 14 days.`),
    E('teacher-have-account-invite', 'teacher', 'Getting in', 'invitation_or_seat', 'T1', `I already have an account and opened my school's invitation. What do I click?`,
      `If you are signed in, select Accept Invitation. If you are not, enter your password and select Sign In and Accept Invitation. If you forgot your password, the Forgot your password link sends a reset email and brings you back to the invitation afterward.`),
    E('invite-expired-message', 'teacher', 'Getting in', 'invitation_or_seat', 'T1', `My invitation says it has expired, or was used, or at the last step it says "This invitation has expired."`,
      `Invitations last 14 days, and the date is checked again at the final step, so a link you opened once can still be refused if you come back after the 14 days. An invitation can also be used only once. Ask your school administrator to resend or extend it.`),
    E('invite-revoked', 'teacher', 'Getting in', 'invitation_or_seat', 'T1', `The invitation page says "This invitation has been revoked." Can I still join?`,
      `Not with that link. A cancelled invitation cannot be reused or resent. Ask your school administrator to send a new invitation to the same email address.`),
    E('invite-wrong-account', 'teacher,parent', 'Getting in', 'invitation_or_seat', 'P1', `The invitation page says "Sign out below to accept it with the correct account."`,
      `An invitation belongs to the email address it was sent to, and you are signed in with a different one. Press the sign-out button on that page, then accept with the invited address. To use another address, ask the person who invited you to send a new invitation to it.`),
    E('invite-license-not-active', 'teacher', 'Getting in', 'invitation_or_seat', 'T1', `The invitation page says "License not yet active."`,
      `Your school's license is not open yet. Registration opens once the school's payment or purchase order has been received. Nothing is wrong with your link. Check back later, or ask your school administrator when the license will be active.`),
    E('teacher-register', 'teacher', 'Getting in', 'invitation_or_seat', 'T2', `Can I register myself with my school email?`,
      `Yes. Use Teacher Registration in the footer, enter your school email address and select Check Eligibility. It checks whether your school's domain has an active license with a free seat. If it does, your seat is reserved and you create your account.`),
    E('reg-no-school-license', 'teacher', 'Getting in', 'invitation_or_seat', 'T2', `Registration says "We don't have a school license on file for your email domain."`,
      `The check matches the part of your email after the @ to a school license. It fails if you used a personal address, or a different school address than the one the license was bought for. Try your school address, or ask your administrator which domain the license uses.`),
    E('reg-license-full', 'teacher', 'Getting in', 'invitation_or_seat', 'T2', `Registration says "Your school's license is full. All available seats are taken."`,
      `Every seat is already used or reserved by an invitation. Choose Notify School Admin and we email the school's license contact. We send one notice per school and reason every 24 hours, so a second press says "Admin was already notified recently." You can also buy a single-teacher license of your own.`),
    E('reg-license-not-active', 'teacher', 'Getting in', 'invitation_or_seat', 'T2', `Registration says "Your school has a license order in progress" or "isn't active yet."`,
      `The first means the order is in but the license is still pending. The second means a license exists but is not active right now, for example payment pending or the license period has ended. Either way you cannot reserve a seat yet, and your administrator can tell you more.`),
    E('teacher-register-verify', 'teacher', 'Getting in', 'cant_sign_in', 'T2', `I signed up but I can't sign in yet.`,
      `Check your email for our message and select the link inside before you sign in. The account is ready once your address is verified.`,
      ['Open the email from us.', 'Select the link.', 'Sign in on Teacher Login.']),
    E('active-license-required', 'teacher', 'Using your license', 'billing_or_license', '', `It says "Active license required", or "An active license is required to assign lessons."`,
      `Your account does not hold a working seat right now. Common reasons are an invitation not yet accepted, a seat your administrator deactivated or removed, a license that is pending or past its end date, or an ended trial. Ask your school administrator to check the roster.`),
    E('trial-ended-convert', 'teacher', 'Using your license', 'billing_or_license', '', `My trial ended and Convert to Annual Access says "No active trial found."`,
      `The online convert option only works while the trial is still running. After the end date the trial is marked expired overnight, its seat is switched off and you are signed out. Send us a request to buy a license.`),
    E('teacher-classroom', 'teacher', 'Classrooms and students', 'students_or_classroom', 'T3', `How do I create a classroom and add students?`,
      `On My Classrooms, create the classroom, then add students one at a time or paste a list. Each student gets a username and a PIN. You can also share the classroom's join code so students join on their own.`),
    E('teacher-csv-format', 'teacher', 'Classrooms and students', 'students_or_classroom', 'T3', `How do I import a whole class from a list?`,
      `Select Import CSV and paste one student per line: name, then an optional student number, then an optional PIN. Leave the PIN off and we make a random 6-digit one. Students never need an email.`),
    E('teacher-pins-gone', 'teacher', 'Classrooms and students', 'students_or_classroom', 'T3', `I imported my class and lost the usernames and PINs.`,
      `PINs are stored scrambled, so they cannot be shown again after the import. Copy the list when it appears. If a student forgets theirs, select Reset PIN beside their name and set a new one.`),
    E('student-username-format', 'teacher,student', 'Classrooms and students', 'students_or_classroom', 'T3', `Why is a student's username something like "alex2" and not their full name?`,
      `A username is the first word of the display name in lowercase letters and numbers, up to 20 characters. If anyone in Fixer Nation already has it, a number is added, so the next Alex becomes alex2.`),
    E('student-pin-rules', 'teacher', 'Classrooms and students', 'students_or_classroom', 'T6', `Reset PIN shows "Error saving PIN", or Add Student shows "Name and PIN required."`,
      `A PIN must be 4 to 6 digits, numbers only, and adding a student needs both a name and a PIN. PINs cannot be shown again after saving, so write them down.`),
    E('teacher-join-code', 'teacher', 'Classrooms and students', 'students_or_classroom', 'T3', `Where is my classroom's join code, and what if it gets shared too widely?`,
      `Every classroom has an 8-character join code, and the Copy button copies it. Select Regenerate Join Code to stop the old code working for new students. You confirm first, and students already in the class are not affected.`),
    E('teacher-archive', 'teacher,student', 'Classrooms and students', 'students_or_classroom', 'T3', `My students can't sign in and I archived the classroom.`,
      `Archive Classroom closes the classroom, and students cannot sign in until you bring it back. You can unarchive it any time.`),
    E('teacher-student-cant-sign-in', 'teacher', 'Classrooms and students', 'students_or_classroom', 'T6', `A student can't sign in.`,
      `Most sign-in trouble is a wrong PIN or a username typed as a name.`,
      ['Check that they are typing their username, not their name. You can see it on the Students tab.', 'If they forgot the PIN, select Reset PIN beside their name and give them the new one.', 'If the page says they are locked, five wrong tries in a row locks a username for about 15 minutes. Select Unlock beside their name to let them try again right away.']),
    E('student-sign-in-blocked', 'teacher,student', 'Classrooms and students', 'students_or_classroom', 'T6', `A student with the right PIN sees "Invalid username or PIN", or "This classroom has been archived."`,
      `A deactivated student gets "Invalid username or PIN" even with the right PIN until the teacher reactivates them. If the classroom is archived, students cannot sign in or see lessons until it is unarchived. Teachers fix both on the classroom page.`),
    E('teacher-invite-parent', 'teacher', 'Classrooms and students', 'parents', 'T6', `How do I invite a parent?`,
      `On the Students tab, select Invite Parent beside the student, enter the parent's email, and add a short note if you like. The link works for 14 days. Each child needs their own invitation, and one parent account can follow several children.`),
    E('teacher-parent-link-expired', 'teacher', 'Classrooms and students', 'parents', 'T6', `A parent's invitation link expired.`,
      `Revoke the old invitation in the list below the students, then invite the parent again. If you would rather not, send us a request and we can extend it by 14 days.`),
    E('teacher-assign', 'teacher', 'Assignments and progress', 'students_or_classroom', 'T4', `How do I assign a lesson or a brain game?`,
      `Open your classroom and select the Assignments tab. Choose Assign Lesson or Assign Game, pick one, set a due date if you want, and select Assign. Students see assigned work the next time they sign in, and can only open what you assigned.`),
    E('assign-lesson-list', 'teacher', 'Assignments and progress', 'students_or_classroom', 'T4', `In Assign Lesson I only see some lessons, or it says "No available lessons. Check your license."`,
      `The list shows lessons from your own library that are not yet assigned to that classroom. If your library is empty it shows all published lessons. The empty message means everything is already assigned, or your sign-in or license is not working.`),
    E('teacher-game-not-listed', 'teacher', 'Assignments and progress', 'students_or_classroom', 'T4', `The game I want isn't in the Assign Game list.`,
      `The list starts with games that fit your classroom's grade. Tick the box to show games for every grade band and you can choose any game.`),
    E('teacher-unassign', 'teacher', 'Assignments and progress', 'students_or_classroom', 'T4', `I assigned the wrong lesson. How do I take it back?`,
      `Select Remove next to the assignment and confirm. Students stop seeing it.`),
    E('teacher-progress-where', 'teacher', 'Assignments and progress', 'students_or_classroom', 'T5', `How do I see who has finished a lesson and what they wrote?`,
      `Open the Progress tab in your classroom. Each assigned lesson has a card with how many started and finished. Select Details for quiz averages and a table by student, then select a row to read their reflections from before and after the lesson.`),
    E('teacher-quiz-reset', 'teacher,student', 'Assignments and progress', 'students_or_classroom', 'T5', `A student submitted a quiz too early and needs another try.`,
      `A quiz can be submitted once per lesson, though answers are saved as a draft until the student submits. In the Progress details, select Reset next to the student's score and confirm. That clears the earlier answers.`),
    E('teacher-game-results', 'teacher', 'Assignments and progress', 'other', 'T5', `Where do I see how my class did on a brain game?`,
      `On the Assignments tab, select Results next to the game. You see how many students finished, how many times it was played, the average score, and each student's first and latest score. You can export it.`),
    E('quiz-grading', 'teacher', 'Assignments and progress', 'students_or_classroom', 'T5', `Are the quizzes graded for me?`,
      `Yes. Digital quizzes are scored when a student submits them, and you see the scores in your classroom dashboard. Every quiz also comes with an answer key.`),
    E('teacher-library', 'teacher', 'Lessons', 'other', 'T7', `My lesson library is full, or I can't remove a lesson.`,
      `Your library has a limit on how many lessons it holds and how many times you can swap one out. The page shows both numbers. If you need more room, send us a request.`),
    E('teacher-level-mismatch', 'teacher', 'Lessons', 'other', 'T7', `Adding a lesson shows "Curriculum level mismatch" and asks "Add it anyway?"`,
      `Nothing is wrong. The lesson is written for grade levels other than the ones on your account. You can add it anyway, or use Choose your grade levels to change yours. At least one level is required.`),
    E('teacher-swap-vs-assigned', 'teacher', 'Lessons', 'other', 'T7', `If I swap a lesson out of my library, do my classes lose it?`,
      `No. Lessons you already assigned to your classes stay assigned. Choosing Swap or remove on a plan uses one swap, and the page shows how many you have left.`),
    E('teacher-community', 'teacher', 'Community', 'other', 'M1', `How do I find and join my community groups?`,
      `Open Community and use Browse to find groups for your school and interests. Your school's group is private to the people at your school.`),
    E('community-who-can-use', 'teacher,school,district', 'Community', 'other', 'M1', `I can't find the Community, or my student can't use it.`,
      `The community is for people with an active Fixer Nation license: licensed teachers and school or district administrators. Students and parents have no access.`),
    E('community-leave-group', 'teacher,school,district', 'Community', 'other', 'M1', `How do I leave a community group, and can I rejoin?`,
      `Select Leave beside the group and confirm. You can add it back any time from Browse Groups. A small number beside a group means unread posts, and it clears when you open the group.`),
    E('community-post-blocked', 'teacher,school,district,student', 'Community', 'something_broke', 'M2', `My post, comment, reflection or goal was not saved. It says "This content cannot be shared because it may violate FNE or your school's safety guidelines."`,
      `Reflections, goals, Community posts, comments and messages are checked automatically before they are saved. Blocked text is not posted, so reword it and try again. If you see "We're unable to verify this content right now," the check was unavailable and nothing was posted, so try again shortly.`),
    E('community-attachments', 'teacher,school,district', 'Community', 'other', 'M2', `What can I attach to a community post?`,
      `Use the camera for a photo, the film icon for a video, or the paperclip for a document such as a PDF or Word file. You can attach up to 5 files, each up to 100 MB. A YouTube or Vimeo link plays inside your post.`),
    E('community-message-colleague', 'teacher,school,district', 'Community', 'other', 'M3', `How do I send a private message to another member?`,
      `In the Members list on the right, type at least two letters of a name to search, then select the member and write your message. Direct messages are private between you and one other member.`),
    E('community-profile-visible', 'teacher,school,district', 'Community', 'other', 'M4', `What can other community members see about me?`,
      `Other members see your name, email, school and bio only if you check Share my profile with community members. If it is unchecked they see just your name and school. A second box controls whether your Brain Game badges show.`),

    // ================= Students
    E('student-pin', 'student', 'Signing in', 'students_or_classroom', 'S1', `My PIN doesn't work, or it says I'm locked.`,
      `Make sure you typed your username, not your name. If it still fails, ask your teacher. They can give you a new PIN or unlock you right away. If you wait about 15 minutes, the lock goes away on its own.`),
    E('student-username', 'student', 'Signing in', 'students_or_classroom', 'S1', `I forgot my username.`,
      `Ask your teacher. Your username is on your class list.`),
    E('student-join', 'student', 'Getting started', 'students_or_classroom', 'S1', `How do I join my class?`,
      `Open Student Login, choose Join a Classroom, and type the join code your teacher gave you. Add your name and choose a PIN of 4 to 6 digits. Write down your username and PIN, because you need both to sign in next time.`),
    E('join-code-not-found', 'student', 'Getting started', 'students_or_classroom', 'S1', `Joining says "Classroom not found" and tells me to check my join code.`,
      `A join code has 8 letters and numbers and never uses I, O, 0 or 1. It stops working if your teacher made a new code or archived the class. If many wrong codes come from one network in a short time, joining pauses for everyone there with "Too many attempts."`),
    E('student-sign-in-again', 'student', 'Signing in', 'students_or_classroom', 'S1', `Do I type the class code every time I sign in?`,
      `No. After you join, go back to the sign-in page and type your username and PIN. You do not need the class code again.`),
    E('join-name-taken', 'student', 'Getting started', 'students_or_classroom', 'S1', `After I joined, a note says "someone already joined this classroom under that name."`,
      `That name was already in the class and your PIN did not match, so a new account with a new username was made. If the first account was yours, sign in with its username and PIN, and tell your teacher so they can check.`),
    E('student-quiz-one-try', 'student', 'Lessons', 'students_or_classroom', 'S2', `I submitted my quiz. Can I try again?`,
      `You get one try when you submit. You can use Save Progress to come back later before you submit. If you need another try, ask your teacher, who can reset your score.`),
    E('student-finish-lesson', 'student', 'Lessons', 'students_or_classroom', 'S2', `How does my teacher know I finished?`,
      `When you have finished everything in a lesson, select Mark as Complete. Your teacher will see that you finished. Some older brain games ask you to select Mark as Done instead.`),
    E('student-goals-history', 'student', 'Lessons', 'other', 'S3', `Where are my goals and old lessons?`,
      `Select My Goals and History at the top of the page. My Goals shows your open and finished goals, and Lesson History lists the lessons you have done, which you can open again.`),
    E('student-flow', 'student,parent,teacher', 'Lessons', 'students_or_classroom', 'S2', `What do students do during a lesson?`,
      `Students watch a short video, write a reflection about the issue, take a short quiz, and set a personal goal. The same parts repeat every day so the routine feels familiar.`),
    E('brain-games-saved', 'student,teacher', 'Brain Games', 'other', 'S4', `Are my Brain Game scores and badges saved?`,
      `Anyone can play, but your scores and badges are saved when you are signed in. After a round you see your score, accuracy, time and experience points, and your level and best score show on each game card.`),
    E('brain-games-find', 'student,teacher', 'Brain Games', 'other', 'S4', `How do I find a game for a certain skill or grade band?`,
      `Under Choose a Game, use the filter buttons to narrow the list by grade band or by the skill a game builds. Select All to see everything again. Each card says what the game works on, and Play Now starts it.`),
    E('brain-badges-show', 'student,teacher', 'Brain Games', 'other', 'S4', `Where are my badges, and how do I show them off?`,
      `Badges are on their own page. Earned badges are in color, and the ones still to win are shown so you know what to aim for. You can choose which badges to feature.`),
    E('brain-games-dashboard', 'student', 'Brain Games', 'other', 'S4', `Where do I see my streak and progress?`,
      `Go back to the library and select View full dashboard under Your Progress. It shows your level and experience, your streak of days played, your totals, a card for each game you have played, and your recent games.`),

    // ================= Parents
    E('parent-link', 'parent', 'Getting started', 'parents', 'P1', `My invitation link doesn't work.`,
      `Invitation links last 14 days. If yours has expired or will not open, ask your child's teacher to invite you again, or send us a request with your child's class and we will help.`),
    E('parent-invite-used', 'parent', 'Getting started', 'parents', 'P1', `The invitation page says "This invitation has already been used."`,
      `An invitation can be accepted only once, so it was already accepted with that email address. Sign in on the parent sign-in page with that same email. If you do not remember the password, use Forgot password.`),
    E('parent-already-account', 'parent', 'Getting started', 'parents', 'P1', `I already have a parent account. Do I create another?`,
      `No. If you already have an account, sign in and accept the invitation instead. New parents enter a first name, last name and a password of at least 8 characters, then select Create Account and Accept Invitation.`),
    E('parent-next-time', 'parent', 'Getting started', 'cant_sign_in', 'P1', `How do I get back in after the first time?`,
      `Sign in from the Parent Login page with your email and password. The email must be the one your child's teacher invited.`),
    E('parent-no-children', 'parent', 'Seeing progress', 'parents', 'P1', `My parent page says "No children linked yet."`,
      `A child appears only after you accept the personal invitation the teacher sends for that child. Each child needs their own invitation, and one parent account can follow several children. Check your email, or ask the teacher to send it.`),
    E('parent-see', 'parent', 'Seeing progress', 'parents', 'P1', `What can I see about my child?`,
      `You can see whether each lesson is done and the lesson resources. You cannot see quiz answers or what your child wrote.`),
    E('parent-lesson-status', 'parent', 'Seeing progress', 'parents', 'P1', `What do Completed, In progress and Not started mean, and where are the lesson materials?`,
      `Each assigned lesson shows one of those labels, and a due date if the teacher set one. Select View resources to see an overview, objectives, materials and videos. The teacher copy, student handout and classroom poster can be viewed when they are available.`),
    E('parent-devices', 'parent', 'Getting started', 'parents', '', `Do I need to download an app?`,
      `No. The parent portal runs in a web browser on a phone, tablet or computer. You set a password from your invitation email and sign in whenever you like.`),
    E('take-home-guides', 'parent', 'At home', 'parents', '', `How can I talk with my child about a lesson?`,
      `Each lesson has a take-home discussion guide with conversation starters tied to what your child learned, and the parent portal has lesson summaries and activity ideas.`),
    E('parent-privacy', 'parent', 'Privacy', 'other', '', `How is my child's information protected?`,
      `Students sign in with a username and PIN, with no email address. Only the student, their teacher and authorized Fixer Nation staff can see their information. Read the Student Data Privacy page for the full details.`),

    // ================= Pricing, buying and getting in touch (answers supplied by the owner, 2026-11-05)
    E('license-price', 'school,district,teacher', 'Pricing and buying', 'billing_or_license', '', `How much does a license cost?`,
      `Pricing depends on the size of your school or district, so we give a quote instead of a fixed price list. Fill in the inquiry form on the School and District Licensing page, or send us a request, and we will put one together. There is no commitment.`),
    E('refunds', 'school,district,teacher', 'Pricing and buying', 'billing_or_license', '', `Can I get a refund or cancel?`,
      `Refunds are handled case by case. Send us a request through Get help or the Contact page, and we will talk it through with you.`),
    E('free-trial-demo', 'school,district,teacher', 'Pricing and buying', 'billing_or_license', '', `Is there a free trial or a demo?`,
      `Free trials and demos are arranged case by case. Send us a request or use the Contact page to talk about what would help your school.`),
    E('discounts', 'school,district', 'Pricing and buying', 'billing_or_license', '', `Do you offer discounts?`,
      `Send us a request for guidance on discounts, and tell us about your school or district and how many teachers you have.`),
    E('tax-forms', 'school,district', 'Pricing and buying', 'billing_or_license', '', `How do I get an invoice, a W-9 or a tax-exempt form?`,
      `Send us a request and tell us which form you need, and we will point you to the right one.`),
    E('how-renewal-works', 'school,district', 'Pricing and buying', 'billing_or_license', '', `How does renewing a license work?`,
      `We send renewal reminders before your license ends, with full instructions. The banner at the top of your portal also turns yellow when 30 days or fewer are left. If you have not seen a reminder, send us a request.`),
    E('office-hours', 'everyone', 'Getting help', 'other', '', `How do I reach you, and what are your office hours?`,
      `Use the Contact page, or send a request through Get help, and we reply by email. Office hours are 8 a.m. to 5 p.m., Monday through Friday.`),
    E('supported-devices', 'everyone', 'Using Fixer Nation', 'something_broke', '', `Which devices and browsers does Fixer Nation work on?`,
      `Any device with a working web browser, including Chromebooks and iPads. Chrome is preferred, so if something looks wrong, try it in Chrome first.`),
    E('google-clever-sso', 'school,district,teacher', 'Using Fixer Nation', 'other', 'A3', `Does Fixer Nation work with Google Classroom, Clever, ClassLink or single sign-on?`,
      `There is no connection to Google Classroom, Clever or ClassLink. Teachers and administrators sign in with an email and password, or with Continue with Microsoft. Students sign in with a username and PIN from their teacher, so there are no student accounts to sync. Send us a request if a district integration matters to you.`),
    E('training', 'school,district,teacher', 'Using Fixer Nation', 'other', '', `Do you offer training for teachers and administrators?`,
      `Send us a request for guidance on training. In the meantime, the Help Videos page has short walkthroughs for administrators, teachers, students and parents.`),
    E('accessibility', 'everyone', 'Using Fixer Nation', 'other', '', `Is Fixer Nation accessible for students with disabilities?`,
      `Send us a request for guidance on accessibility, and tell us what your students need so we can answer for your situation.`),

    // ================= Drafts: pricing, promises about timing, privacy and legal wording, research claims. Hidden until the owner reads them.
    E('student-data-retention', 'parent,school,district', 'Privacy', 'other', '', `How long is student data kept?`,
      `We keep student information while a school is using Fixer Nation. When a teacher removes a student, the student disappears from the classroom but the records are not erased. We delete a student's data, or a whole classroom's, whenever the school or a parent asks, and Brain Games activity older than about 13 months is deleted on its own.`),
    E('student-no-email', 'student,parent', 'Privacy', 'students_or_classroom', '', `Does my child need an email address or a public profile?`,
      `No. Student accounts do not use an email address, and there are no public profiles, social feed or advertising. Students join with a code from their teacher and see only the lessons their teacher assigned.`),
    E('student-data-collected', 'parent,school', 'Privacy', 'other', '', `What information does Fixer Nation collect about students?`,
      `Only what a classroom needs to run: a display name and username (no email), lesson completion, quiz answers and scores, written reflections, personal goals, class enrollment and Brain Games results. We do not collect IP addresses, browser or device details, or location data from student accounts, and the student portal has no behavioral analytics or third-party tracking. Student data is never sold.`),
    E('student-data-sale-ads', 'parent,school', 'Privacy', 'other', '', `Is student data sold or used for advertising?`,
      `Never. Students do not see advertising, student data is not sold, and engagement data is not used to target ads. No third-party analytics service receives student-identifiable data.`),
    D('ferpa-requests', 'parent,school', 'Privacy', 'other', '', `How do I ask to see my child's records?`,
      `When a school licenses Fixer Nation, student data counts as education records under FERPA. Send FERPA-related requests to your school's administration, and the school can work with us. You can also use the Contact page.`),
    E('data-deletion', 'school,district,parent', 'Privacy', 'other', '', `How do we request deletion of student data?`,
      `Send the request through the Contact page and say whose data it is and what you want removed. We will delete any data you ask us to, for any user.`),
    E('privacy-paperwork', 'school,district', 'Privacy', 'billing_or_license', '', `Can you help with our district privacy review?`,
      `Yes. We will help any district with privacy concerns, questions or reviews as part of our concierge service. Contact the education team through the Contact page and tell us what your review needs.`),
    E('site-visitor-privacy', 'everyone', 'Privacy', 'other', '', `What does the website collect about me, and can I opt out?`,
      `Only what you type into a form, such as your name and email. The site also counts which pages get viewed, tied to a random ID that lives only in your browser tab and carries no name, email or IP address. You can turn that off on the Privacy Choices page, where you can also ask to see, correct or delete your information.`),
    E('content-focus', 'parent,school', 'Privacy', 'other', '', `Are the lessons about politics?`,
      `No. Every lesson is written and curated around the SEL core competencies, with a focus on character topics such as resilience, responsibility, empathy and decision-making. Contested and political subjects are left out.`),
    E('parent-preview', 'parent', 'Seeing progress', 'parents', '', `Can I preview what my child will be taught?`,
      `Yes. Once your child's teacher invites you to the parent portal, you can see your child's progress and the SEL lessons currently assigned to the class.`),
    E('outcome-evidence', 'school,district', 'Research', 'other', '', `Is there research showing Fixer Nation improves results?`,
      `Not from us yet. National research has already looked at SEL and Portrait of a Graduate programs and found them successful, but Fixer Nation Education has not run its own research on its programs. That may change in the future.`),
    E('casel-alignment', 'school,district,teacher', 'Research', 'other', '', `Is Fixer Nation endorsed by CASEL?`,
      `Not yet. We map our lessons to the five CASEL competencies as our own thematic alignment, which is not a CASEL review, endorsement or certification. We plan to look at partnering with CASEL once the program has been through its first year of use.`),
    E('teacher-seat-cost', 'teacher', 'Licensing', 'billing_or_license', '', `Do I pay anything if my school already has a license?`,
      `No. A teacher invited by a school or district administrator pays nothing and uses one seat of the group license. Register with your school email so we can match you to it.`),
    E('teacher-single-license-price', 'teacher', 'Licensing', 'billing_or_license', '', `How much is a single-teacher license?`,
      `Every price is on the Licenses page at fixernationeducation.com/licenses.html, and it always shows the current one.`),
    E('quote-response-time', 'school,district', 'Licensing', 'billing_or_license', '', `How quickly will you reply to a licensing inquiry?`,
      `Usually within one to two business days.`),
    E('setup-time', 'school,district', 'Licensing', 'billing_or_license', '', `How long does it take to get teachers started?`,
      `About two business days once a quote is approved and we have your purchase order. Orders paid by credit card are set up in one business day, and many features are self-service from the start.`),
    E('parent-access-cost', 'parent', 'Getting started', 'parents', '', `Does the parent portal cost anything?`,
      `No. The parent portal is 100% free. You need an invitation from your child's teacher.`),
    E('district-licensing', 'district', 'Licensing', 'billing_or_license', '', `What does a district license add?`,
      `A district license lets a group of schools buy one block of licenses together and take advantage of bulk pricing. Contact the education team to scope a plan for your district.`)
  ];

  function visible(preview) {
    return ENTRIES.filter(function (e) { return preview || e.reviewed; });
  }
  function byId(id) { for (var i = 0; i < ENTRIES.length; i++) if (ENTRIES[i].id === id) return ENTRIES[i]; return null; }
  function forAudience(entries, aud) {
    if (!aud || aud === 'everyone') return entries;
    return entries.filter(function (e) { return e.for.indexOf(aud) !== -1 || e.for.indexOf('everyone') !== -1; });
  }
  // Matches every typed word against the question, answer, steps and topic (case-insensitive).
  function search(entries, text) {
    var words = String(text || '').toLowerCase().split(/\s+/).filter(Boolean);
    if (!words.length) return entries;
    return entries.filter(function (e) {
      var hay = (e.q + ' ' + e.a + ' ' + e.topic + ' ' + (e.steps || []).join(' ')).toLowerCase();
      return words.every(function (w) { return hay.indexOf(w) !== -1; });
    });
  }

  window.FNHelpCenter = { audiences: AUDIENCES, entries: ENTRIES, visible: visible, byId: byId, forAudience: forAudience, search: search };
})();
